package br.com.erp.pos;
import br.com.erp.auth.*;
import br.com.erp.shared.WorkflowSupport;
import java.math.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service
public class CommercialBenefits {
 private final JdbcTemplate db;private final WorkflowSupport flow;
 public CommercialBenefits(JdbcTemplate db,WorkflowSupport flow){this.db=db;this.flow=flow;}
 @Transactional public void originate(Actor a,UUID sale,UUID branch,BigDecimal total,SaleContracts.Input input){UUID seller=input.salespersonId(),customer=input.loyaltyCustomerId();if(input.credit()!=null){if(customer!=null&&!customer.equals(input.credit().customerId()))throw flow.bad("Cliente de fidelidade difere do crediário.");customer=input.credit().customerId();}BigDecimal percent=BigDecimal.ZERO,points=BigDecimal.ZERO;if(seller!=null){var rows=db.query("SELECT commission_percent FROM salesperson WHERE tenant_id=? AND id=? AND branch_id=? AND active=TRUE",(r,i)->r.getBigDecimal(1),a.tenantId(),seller,branch);if(rows.isEmpty())throw flow.missing("Vendedor ativo da filial não encontrado.");percent=rows.getFirst();}if(customer!=null){flow.require(a,"customer:read");if(db.queryForObject("SELECT COUNT(*) FROM customer WHERE tenant_id=? AND id=? AND active=TRUE",Long.class,a.tenantId(),customer)!=1)throw flow.missing("Cliente ativo não encontrado.");var rules=db.query("SELECT points_per_real FROM loyalty_policy WHERE tenant_id=? AND branch_id=? AND active=TRUE",(r,i)->r.getBigDecimal(1),a.tenantId(),branch);if(!rules.isEmpty())points=total.multiply(rules.getFirst()).setScale(0,RoundingMode.DOWN);}if(points.compareTo(new BigDecimal("9999999999999999999"))>0)throw flow.bad("Pontuação da venda excede o limite permitido.");BigDecimal commission=total.multiply(percent).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP);db.update("INSERT INTO sale_commercial(tenant_id,sale_id,salesperson_id,customer_id,commission_percent,commission_amount,points) VALUES(?,?,?,?,?,?,?)",a.tenantId(),sale,seller,customer,percent,commission,points);journal(a,sale,branch,seller,customer,sale,"SALE",commission,points,"Apuração sobre venda concluída; não é pagamento de comissão.");}
 private void journal(Actor a,UUID sale,UUID branch,UUID seller,UUID customer,UUID source,String kind,BigDecimal commission,BigDecimal points,String note){db.update("INSERT INTO commercial_ledger(id,tenant_id,branch_id,sale_id,salesperson_id,customer_id,source_id,kind,commission,points,note,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),a.tenantId(),branch,sale,seller,customer,source,kind,commission,points,note,a.userId());}
 @Transactional public void reverse(Actor a,UUID sale,UUID source,boolean cancel){var rows=db.queryForList("SELECT c.*,s.branch_id,s.total FROM sale_commercial c JOIN pos_sale s ON s.tenant_id=c.tenant_id AND s.id=c.sale_id WHERE c.tenant_id=? AND c.sale_id=?",a.tenantId(),sale);if(rows.isEmpty())return;var r=rows.getFirst();BigDecimal total=(BigDecimal)r.get("total"),returned=cancel?total:db.queryForObject("SELECT COALESCE(SUM(total),0) FROM pos_sale_return WHERE tenant_id=? AND sale_id=?",BigDecimal.class,a.tenantId(),sale);BigDecimal amount=((BigDecimal)r.get("commission_amount")).multiply(returned).divide(total,2,RoundingMode.HALF_UP),points=((BigDecimal)r.get("points")).multiply(returned).divide(total,0,RoundingMode.DOWN);var net=db.queryForMap("SELECT COALESCE(SUM(commission),0) AS c,COALESCE(SUM(points),0) AS p FROM commercial_ledger WHERE tenant_id=? AND sale_id=? AND kind IN ('RETURN','CANCEL')",a.tenantId(),sale);journal(a,sale,(UUID)r.get("branch_id"),(UUID)r.get("salesperson_id"),(UUID)r.get("customer_id"),source,cancel?"CANCEL":"RETURN",amount.negate().subtract((BigDecimal)net.get("c")),points.negate().subtract((BigDecimal)net.get("p")),"Estorno proporcional sobre valores históricos da venda.");}
}
